mapper.select:
SELECT

FROM schedule s
JOIN doctor d ON s.doctor_id = d.doctor_id
JOIN `user` u ON d.user_id = u.user_id


        AND s.doctor_id = #{doctorId}


        AND d.department = #{department}


        AND s.schedule_date >= #{startDate}


        AND s.schedule_date <= #{endDate}


ORDER BY s.schedule_date, s.time_period, s.doctor_id

SELECT

FROM schedule s
JOIN doctor d ON s.doctor_id = d.doctor_id
JOIN `user` u ON d.user_id = u.user_id


        AND s.doctor_id = #{doctorId}


        AND s.schedule_date >= #{startDate}


        AND s.schedule_date <= #{endDate}


ORDER BY s.schedule_date, s.time_period
